/** Where the printable calendar PDFs live (public/downloads, generated by npm run calendar:pdf). */
export const PDF_LOCALES = ['en', 'fr', 'ar'] as const;
export type PdfLocale = (typeof PDF_LOCALES)[number];

export const calendarPdfFile = (year: number, locale: PdfLocale) =>
  `mbsc-training-calendar-${year}-${locale}.pdf`;

/** Public URL path of a calendar PDF. */
export const calendarPdfPath = (year: number, locale: PdfLocale) =>
  `/downloads/${calendarPdfFile(year, locale)}`;

/** Manifest written next to the PDFs: the sha256 of each calendar JSON they were made from. */
export const PDF_MANIFEST = 'calendar-pdf.json';

/**
 * The PDF's public path if it exists and was generated from the current calendar data, else null
 * (the site then hides the download button instead of linking to a missing or wrong file).
 * Build-time only: reads public/downloads and src/content/calendars.
 */
export async function currentPdf(year: number, locale: PdfLocale): Promise<string | null> {
  const { readFile } = await import('node:fs/promises');
  const { createHash } = await import('node:crypto');
  const { pathToFileURL } = await import('node:url');
  // The project root (builds and scripts run from it). Not import.meta.url: Astro bundles this file.
  const root = pathToFileURL(`${process.cwd()}/`);
  try {
    const manifest = JSON.parse(
      await readFile(new URL(`public/downloads/${PDF_MANIFEST}`, root), 'utf8'),
    ) as Record<string, string>;
    const source = await readFile(new URL(`src/content/calendars/${year}.json`, root));
    const hash = createHash('sha256').update(source).digest('hex');
    await readFile(new URL(`public/downloads/${calendarPdfFile(year, locale)}`, root));
    return manifest[calendarPdfFile(year, locale)] === hash ? calendarPdfPath(year, locale) : null;
  } catch {
    return null;
  }
}
